from marshmallow import Schema, fields, validate

from ddb.feature.schema import FeatureSchema

TRAEFIK_V2 = 2
TRAEFIK_V3 = 3

SSL_CONFIG_TEMPLATE = """
# This configuration file has been automatically generated by ddb
[[tls.certificates]]
  certFile = "{{_local.certFile}}"
  keyFile = "{{_local.keyFile}}"

""".lstrip()

# traefik v3 dropped the `{name:regex}` patterns v2 inherited from gorilla/mux, and matches
# such paths with PathRegexp instead. Each form is silently ignored by the other version:
# the router is loaded and reported as enabled, and never matches anything.
_PATH_PREFIX_MATCHERS = {
    TRAEFIK_V2: "PathPrefix(`{{_local.path_prefix}}{regex:$$|/.*}`)",
    TRAEFIK_V3: "PathRegexp(`^{{_local.path_prefix}}($|/.*)`)",
}

_PATH_PREFIX_MATCHER_PLACEHOLDER = "%path_prefix_matcher%"

_EXTRA_SERVICES_CONFIG_TEMPLATE = """
# This configuration file has been automatically generated by ddb
[http.routers]
{%- if _local.https is none or _local.https is sameas false %}
  [http.routers.extra-service-{{_local.id}}]
    rule = "{{_local.rule}}{% if not _local.redirect_to_https and _local.path_prefix %} && \
%path_prefix_matcher%{% endif %}"
    entrypoints = ["http"]
    service = "extra-service-{{_local.id}}"
{%- if _local.redirect_to_https %}
    middlewares = ["extra-service-{{_local.id}}-redirect-to-https"]
{%- elif _local.path_prefix %}
    middlewares = ["extra-service-{{_local.id}}-stripprefix"]
{%- endif %}
{%- endif %}
{%- if _local.https is none or _local.https is sameas true %}
  [http.routers.extra-service-{{_local.id}}-tls]
    rule = "{{_local.rule}}{% if _local.path_prefix %} && %path_prefix_matcher%{% endif %}"
    entrypoints = ["https"]
    tls = true
    service = "extra-service-{{_local.id}}"
{%- if _local.path_prefix %}
    middlewares = ["extra-service-{{_local.id}}-stripprefix"]
{%- endif %}
{%- if _local.certresolver is defined %}
    [http.routers.extra-service-{{_local.service}}-tls.tls]
      certResolver = "{{_local.certresolver}}"
{%- endif %}
{%- endif %}
{%- if _local.redirect_to_path_prefix %}
{%- if _local.https is none and not _local.redirect_to_https or _local.https is sameas false %}
  [http.routers.extra-service-{{_local.id}}-redirect-to-path-prefix]
    rule = "{{_local.rule}}"
    entrypoints = ["http"]
    service = "extra-service-{{_local.id}}"
    middlewares = ["extra-service-{{_local.id}}-redirect-to-path-prefix"]
{%- endif %}
{%- if _local.https is none or _local.https is sameas true %}
  [http.routers.extra-service-{{_local.id}}-redirect-to-path-prefix-tls]
    rule = "{{_local.rule}}"
    entrypoints = ["https"]
    tls = true
    service = "extra-service-{{_local.id}}"
    middlewares = ["extra-service-{{_local.id}}-redirect-to-path-prefix"]
{%- if _local.certresolver is defined %}
    [http.routers.extra-service-{{_local.service}}-tls.tls]
      certResolver = "{{_local.certresolver}}"
{%- endif %}
{%- endif %}
{%- endif %}

{%- if _local.redirect_to_https or _local.path_prefix  %}

[http.middlewares]
{%- if _local.redirect_to_https %}
  [http.middlewares.extra-service-{{_local.id}}-redirect-to-https.redirectScheme]
    scheme = "https"
{%- endif %}
{%- if _local.path_prefix %}
  [http.middlewares.extra-service-{{_local.id}}-stripprefix.stripPrefix]
    prefixes = ["{{_local.path_prefix}}"]
{%- endif %}
{%- if _local.redirect_to_path_prefix %}
  [http.middlewares.extra-service-{{_local.id}}-redirect-to-path-prefix.redirectRegex]
    regex = "^.*$"
    replacement = "{{_local.path_prefix}}"
{%- endif %}
{%- endif %}

[http.services]
  [http.services.extra-service-{{_local.id}}]
    [http.services.extra-service-{{_local.id}}.loadBalancer]
      [[http.services.extra-service-{{_local.id}}.loadBalancer.servers]]
        url = "{{_local.url}}"

""".lstrip()

EXTRA_SERVICES_CONFIG_TEMPLATES = {
    version: _EXTRA_SERVICES_CONFIG_TEMPLATE.replace(_PATH_PREFIX_MATCHER_PLACEHOLDER, matcher)
    for version, matcher in _PATH_PREFIX_MATCHERS.items()
}


class ExtraServiceSchema(Schema):
    """
    Extra Service.
    """

    https = fields.Bool(required=False, allow_none=True, dump_default=None)
    url = fields.String(required=True, allow_none=False, dump_default=None)
    domain = fields.String(required=True, allow_none=True, dump_default=None)
    rule = fields.String(required=False, allow_none=True, dump_default=None)
    redirect_to_https = fields.Boolean(required=False, allow_none=True, dump_default=None)
    path_prefix = fields.String(required=False, allow_none=True, dump_default=None)
    redirect_to_path_prefix = fields.Boolean(required=False, allow_none=True, dump_default=None)


class TraefikSchema(FeatureSchema):
    """
    Traefik feature schema.
    """

    version = fields.Integer(required=True, dump_default=TRAEFIK_V3, validate=validate.OneOf(_PATH_PREFIX_MATCHERS))
    certs_directory = fields.String(required=False, allow_none=True, dump_default=None)
    config_directory = fields.String(required=False, allow_none=True, dump_default=None)
    mapped_certs_directory = fields.String(required=True, dump_default="/certs")
    ssl_config_template = fields.String(required=True, dump_default=SSL_CONFIG_TEMPLATE)
    extra_services = fields.Dict(fields.String(), fields.Nested(ExtraServiceSchema()), dump_default={})
    # Left empty on purpose: the default depends on the traefik version, and is filled by
    # TraefikFeature._configure_defaults.
    extra_services_config_template = fields.String(required=False, allow_none=True, dump_default=None)
